    $lastFetched=\MyBB\Tooling\RepositoryMetadataCache::lastFetchedAt($entries);if($lastFetched!==null)$mybbresourcesCatalogLastSuccess=max((int)($mybbresourcesCatalogLastSuccess??0),$lastFetched);
