    $body='';$tooLarge=false;$headers=[];$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>false,CURLOPT_WRITEFUNCTION=>function($c,$chunk)use(&$body,&$tooLarge){if(strlen($body)+strlen($chunk)>2097152){$tooLarge=true;return 0;}$body.=$chunk;return strlen($chunk);},CURLOPT_HEADERFUNCTION=>function($c,$line)use(&$headers){$length=strlen($line);$separator=strpos($line,':');if($separator!==false)$headers[strtolower(trim(substr($line,0,$separator)))]=trim(substr($line,$separator+1));return $length;},CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>15,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2,CURLOPT_USERAGENT=>'MyBB-Resources-Repository/0.1']);$ok=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);$error=curl_error($ch);$errno=curl_errno($ch);curl_close($ch);if($ok===false)throw \MyBB\Tooling\CatalogClient::classifyTransportFailure($errno,$error,$tooLarge);$decoded=json_decode($body,true);if($status<200||$status>=300||isset($decoded['error'])){$envelope=is_array($decoded['error']??null)?$decoded['error']:[];throw \MyBB\Tooling\CatalogClient::classifyHttpFailure($status,$envelope,'Catalog request failed.',$headers['x-request-id']??null);}if(!is_array($decoded)||!isset($decoded['data'])||!is_array($decoded['data']))throw new \MyBB\Tooling\CatalogException('invalid_api_response','Catalog returned an invalid API response.',false,$status,$headers['x-request-id']??null);$data=$decoded['data'];
    $now=time();$mybbresourcesCatalogLastSuccess=$now;if($cacheAvailable){$entries=\MyBB\Tooling\RepositoryMetadataCache::store($entries,$cacheKey,$data,$now);try{$cache->update('mybbresources_repository_api',$entries);}catch(Throwable){}}
    return $data;
}
function mybbresources_escape(string $s): string { return htmlspecialchars_uni($s); }
function mybbresources_error_message(Throwable $e): string {
    if($e instanceof \MyBB\Tooling\CatalogException)return $e->displayMessage();
    return $e->getMessage();
}
function mybbresources_repository_assert_inactive(array $record,object $cache): void {
    \MyBB\Tooling\PluginLifecycle::assertInactive($record,$cache,'deactivate or verify it in the Plugins page before uninstalling.');
}
function mybbresources_download_release(string $slug,string $version,string $catalog,string $trustedKeys): array {
    if(!preg_match('/^[a-z0-9][a-z0-9-]{1,62}$/',$slug)||!preg_match('/^\d+\.\d+\.\d+(?:[-+][A-Za-z0-9.-]+)?$/',$version))throw new RuntimeException('Invalid plugin identity/version');
    $release=mybbresources_api($catalog.'/plugins/'.rawurlencode($slug).'/releases/'.rawurlencode($version),false);$manifest=$release['manifest']??null;if(!is_array($manifest))throw new RuntimeException('Catalog returned no signed manifest');
    $keys=json_decode((string)file_get_contents($trustedKeys),true,512,JSON_THROW_ON_ERROR);if(!is_array($keys))throw new RuntimeException('Trusted key map is invalid');\MyBB\Tooling\Manifest::validate($manifest);\MyBB\Tooling\Manifest::verifySignature($manifest,$keys);if(($manifest['slug']??null)!==$slug||($manifest['version']??null)!==$version)throw new RuntimeException('Catalog manifest identity does not match the requested release');
    if(!isset($manifest['package']['url'],$manifest['package']['size']))throw new RuntimeException('Manifest has no valid package declaration');$tmp=(new \MyBB\Tooling\CatalogClient('https://plugins.mybbresources.com'))->download($manifest);return [$tmp,$release,$manifest,$keys];
}
if($module==='lifecycle'&&($_SERVER['REQUEST_METHOD']??'GET')==='POST') {
