        if(!empty($impact['conflicts'])&&!$force){echo '<input type="hidden" name="apply" value="0"><label><input type="checkbox" name="force" value="1"> Replace these modified or unmanaged files with the signed release</label> <button type="submit">Review forced replacement</button>';}
        else {if($force)echo '<p><strong>Forced replacement selected:</strong> this signed release will replace the listed existing files.</p><input type="hidden" name="force" value="1">';echo '<input type="hidden" name="apply" value="1"><button type="submit">Confirm and '.($currentVersion!==''?'update':'install').'</button>';}
        echo ' <a href="index.php?module=config-mybbresources_repository">Cancel</a></form>';
        $page->output_footer();
        exit;
    } catch(Throwable $e){if(isset($tmp)&&is_file($tmp))@unlink($tmp);error('Plugin install failed: '.mybbresources_escape(mybbresources_error_message($e)));}
