        $lifecycle='';$canUninstall=true;foreach(($record['files']??[]) as $path=>$fileRecord)if(($fileRecord['role']??'')==='plugin'&&preg_match('#^inc/plugins/([A-Za-z0-9_]+)\.php$#',$path,$match)&&is_file(MYBB_ROOT.$path)&&!is_link(MYBB_ROOT.$path)){$codename=$match[1];$active=isset($activePlugins[$codename]);$ledgerActive=($record['active']??false)===true;if(!$activationKnown||$active||$ledgerActive)$canUninstall=false;if(!$activationKnown)$lifecycle='<span>Activation status unavailable</span>';else{$next=($active||$ledgerActive)?'deactivate':'activate';$label=$active?'Active':($ledgerActive?'Inactive · state sync needed':'Inactive');$lifecycle='<span>'.$label.'</span><form method="post" action="index.php?module=config-mybbresources_repository&amp;repo_action=lifecycle"><input type="hidden" name="my_post_key" value="'.mybbresources_escape($mybb->post_code).'"><input type="hidden" name="slug" value="'.mybbresources_escape((string)$slug).'"><input type="hidden" name="plugin" value="'.mybbresources_escape($codename).'"><input type="hidden" name="state" value="'.$next.'"><button type="submit">'.ucfirst($next).'</button></form>'; }break;}
